82		}
83		if v := find.CreatorID; v != nil {
84			where, args = append(where, "memo.creator_id = "+placeholder(len(args)+1)), append(args, *v)
85		}
86		if v := find.RowStatus; v != nil {
87			where, args = append(where, "memo.row_status = "+placeholder(len(args)+1)), append(args, *v)
