95			where = append(where, fmt.Sprintf("memo.visibility in (%s)", strings.Join(holders, ", ")))
96		}
97		if find.ExcludeComments {
98			where = append(where, "memo_relation.related_memo_id IS NULL")
99		}
100	
101		order := "DESC"
102		if find.OrderByTimeAsc {
103			order = "ASC"
104		}
105		orderBy := []string{}
